#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "core/canvas.h"
#include "hacks/registry.h"
#include "runner/hack_runner.h"
#include "x11shim/pixmap.h"
#include "x11shim/xshim.h"

int main(int argc, char **argv) {
  const char *want = argc > 1 ? argv[1] : "pacman";
  int index = -1;
  for (int i = 0; i < g_hack_count; i++)
    if (strcasecmp(g_hacks[i]->name, want) == 0) index = i;
  if (index < 0) return 2;

  Canvas cv;
  if (canvas_init(&cv, 466, 466, malloc) != 0) return 1;
  HackRunner *r = runner_create(&cv);
  if (!r || runner_start(r, index) != 0) return 1;
  for (int i = 0; i < 50; i++) runner_step(r);

  Display *dpy = xshim_current_display();
  long colour = 0, bitmaps = 0, rows = 0, px_bytes = 0, bitmap_bytes = 0;
  for (struct XshimPixmap *pm = dpy->pixmaps; pm; pm = pm->next) {
    if (pm->depth == 16) {
      colour++;
      rows += pm->h;
      px_bytes += (long)pm->w * pm->h * 2;
    } else {
      bitmaps++;
      bitmap_bytes += (long)pm->stride * pm->h;
    }
  }
  printf("%s: colour pixmaps=%ld rows=%ld pixel_bytes=%ld dirty_array_bytes=%ld\n",
         g_hacks[index]->name, colour, rows, px_bytes, rows * 4);
  printf("  bitmaps=%ld bitmap_bytes=%ld\n", bitmaps, bitmap_bytes);
  printf("  per-pixmap overhead: struct=%zu canvas calloc'd with it\n",
         sizeof(struct XshimPixmap));
  runner_destroy(r);
  canvas_free(&cv);
  return 0;
}

