static int gaps(Canvas *cv, int verbose) {
  int g = 0;
  for (int y = 0; y < cv->h; y++)
    for (int x = 0; x < cv->w; x++) {
      const float r = hypotf(x + 0.5f - 100.0f, y + 0.5f - 100.0f);
      if (r < 93.0f && r > 67.0f && cv->px[y * cv->w + x] != 0xFFFF) {
        g++;
        if (verbose) printf("  gap (%d,%d)\n", x, y);
      }
    }
  return g;
}

static void run(const char *label, int width, int join, int cap, int *xy, int n,
                int closed, int verbose) {
  Canvas cv;
  canvas_init(&cv, 200, 200, malloc);
  Display *dpy = xshim_open_display(&cv);
  XGCValues v;
  v.foreground = 0xFFFF;
  GC gc = XCreateGC(dpy, XSHIM_WINDOW, GCForeground, &v);
  XSetLineAttributes(dpy, gc, width, LineSolid, cap, join);
  stroke_polyline(&cv, gc, xy, n, closed);
  printf("%s: gaps=%d\n", label, gaps(&cv, verbose));
  xshim_close_display(dpy);
  canvas_free(&cv);
}

int main(void) {
  int xy[2 * 600];
  const int n = arc_points(20, 20, 160, 160, 0, 360 * 64, xy, 600);
  run("miter w30", 30, JoinMiter, CapButt, xy, n, 1, 1);
  run("bevel w30", 30, JoinBevel, CapButt, xy, n, 1, 0);
  run("round w30", 30, JoinRound, CapButt, xy, n, 1, 0);
  run("miter w31", 31, JoinMiter, CapButt, xy, n, 1, 0);
  run("miter w29", 29, JoinMiter, CapButt, xy, n, 1, 0);
  run("miter w20", 20, JoinMiter, CapButt, xy, n, 1, 0);
  return 0;
}

